def ver(id,name,file,date,desc,issues,unk=None,oq=None):
    return dict(id=id,name=name,folder="Bias Coil Driver V2",files=[file,file.replace('.kicad_sch','.kicad_pcb')],last_modified=date,status="superseded",
      status_note=issues[0],description=desc[0],description_confidence="medium",issues=desc[1],unknown_parts=unk or [],open_questions=oq or [])

